def deco[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return wrapper

@deco
def a(x: int) -> int:
    """doc"""
    return x

print(a.__name__, a.__doc__)
```

